<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { state, useAction } from '../api'
import { usePagedList } from '../pagination'
import type { Chapter, Edition, MergedChapter, Page } from '../types'
import { titleOf } from '../types'
import Pagination from '../components/Pagination.vue'
const route=useRoute()
const id=computed(() => Number(route.params.id) || null)
const edition=computed(() => state.editions.find(e => e.id===id.value))
const showCreate=ref(false)
const mergedDirectory=ref<HTMLElement>()
async function scrollToMerged() { await nextTick(); mergedDirectory.value?.scrollIntoView?.({block:'start'}) }
const form=ref({ name:'', description:'', output_name:'' })
const { action, run }=useAction()
const appendSource=ref(''), appendRange=ref('')
const pickerSource=ref(''), parts=ref<Chapter[]>([]), composedTitle=ref('')
const listing=usePagedList<Page<MergedChapter> & { edition:Edition }>(() => id.value ? `/editions/${id.value}/chapters` : null)
const picker=usePagedList<Page<Chapter>>(() => pickerSource.value ? `/sources/${pickerSource.value}/chapters` : null)
watch(id, () => { parts.value=[]; action.error=''; action.success='' })
async function create() { await run({ kind:'merge_create', name:form.value.name, description:form.value.description || null, output_name:form.value.output_name || null }); if (!action.error) { showCreate.value=false; form.value={name:'',description:'',output_name:''} } }
async function compose() { await run({ kind:'merge_compose', edition_id:id.value, title:composedTitle.value || null, chapter_ids:parts.value.map(c => c.id) }); if (!action.error) { parts.value=[]; composedTitle.value='' } }
</script>
<template>
  <RouterLink v-if="id" to="/editions" class="back-link">← 全部合并版本</RouterLink>
  <div class="page-heading"><div><h1>{{ id ? edition?.name || '合并版本' : '合并版本' }}</h1><p v-if="id && edition?.description">{{ edition.description }}</p></div><button v-if="!id" class="button primary" @click="showCreate=!showCreate">＋ 创建版本</button><button v-else class="button primary" :disabled="action.busy || !state.connected" @click="run({kind:'export_merged', edition_id:id})">导出合并 TXT</button></div>
  <p v-if="action.error" class="message error" role="alert">{{ action.error }}</p><p v-if="action.success" class="message success" role="status">{{ action.success }} <RouterLink to="/tasks">查看任务 →</RouterLink></p>
  <form v-if="showCreate && !id" class="panel form-panel" @submit.prevent="create"><h2>创建合并版本</h2><div class="form-row"><label>版本名称<input v-model="form.name" required maxlength="200" placeholder="例如：完整合并版"></label><label>输出文件名（可选）<input v-model="form.output_name" maxlength="200" placeholder="默认使用版本名称"></label></div><label>版本说明（可选）<textarea v-model="form.description" maxlength="4000" rows="2" placeholder="记录这个版本的来源和整理方式…"></textarea></label><div class="form-actions"><button class="button primary" :disabled="action.busy || !state.connected">创建版本</button></div></form>
  <section v-if="!id" class="panel"><div class="panel-heading"><div><h2>全部版本 <span class="count">{{ state.editions.length }}</span></h2></div></div><div v-if="!state.loaded" class="empty" role="status">{{ state.connected ? '正在读取合并版本…' : '尚未读取合并版本，请恢复本地服务连接。' }}</div><div v-else-if="!state.editions.length" class="empty"><div class="empty-symbol">⊞</div><h3>暂无合并版本</h3><button class="button" @click="showCreate=true">创建合并版本 →</button></div><div v-else class="edition-list"><RouterLink v-for="item in state.editions" :key="item.id" :to="`/editions/${item.id}`" class="edition-row"><span class="edition-icon">⊞</span><div><h3>{{ item.name }}</h3><p v-if="item.description">{{ item.description }}</p><small>{{ item.output_name }}.txt</small></div><span class="edition-arrow">→</span></RouterLink></div></section>
  <template v-else>
    <div class="detail-grid"><form class="panel form-panel" @submit.prevent="run({kind:'merge_append',edition_id:id,source_id:Number(appendSource),chapters:appendRange})"><h2>按范围追加</h2><p class="hint">每个来源章节分别追加为一个合并章节。</p><label>选择来源<select aria-label="选择来源" v-model="appendSource" required><option value="" disabled>选择书库来源</option><option v-for="source in state.sources" :key="source.id" :value="source.id">{{ source.title }} · {{ source.site_name }}</option></select></label><label>连续目录范围<input v-model="appendRange" required placeholder="例如：1-100"></label><div class="form-actions"><button class="button" :disabled="action.busy || !state.connected">追加到版本末尾</button></div></form>
    <div class="panel form-panel"><h2>版本信息</h2><dl class="info-list"><dt>版本 ID</dt><dd>#{{ id }}</dd><dt>导出文件</dt><dd>{{ edition?.output_name }}.txt</dd><dt>目录章节</dt><dd>{{ listing.total.value }} 章</dd></dl><p class="hint">来源刷新后，导出使用最新正文；缺失正文以占位提示。</p></div></div>
    <section class="panel form-panel"><h2>组合为一个章节</h2><p class="hint">依次添加来源章节，可跨来源选择。以下顺序就是正文拼接顺序。</p><div class="compose-grid"><div><label>从来源选择<select aria-label="从来源选择" v-model="pickerSource"><option value="">选择来源</option><option v-for="source in state.sources" :key="source.id" :value="source.id">{{ source.title }} · {{ source.site_name }}</option></select></label><p v-if="picker.busy.value && !picker.data.value" class="hint" role="status">正在加载来源目录…</p><p v-if="picker.error.value" class="message error" role="alert">{{ picker.error.value }} <button class="text-button" @click="picker.load()">重试加载</button></p><template v-if="pickerSource && picker.data.value"><div class="picker-list"><div v-for="chapter in picker.data.value.items" :key="chapter.id"><span><small>{{ chapter.position }}</small> {{ titleOf(chapter) }}</span><button class="button small" :disabled="picker.busy.value" :aria-label="`添加第 ${chapter.position} 章到组合`" @click="parts.push(chapter)">＋ 添加</button></div></div><Pagination v-model:page="picker.page.value" v-model:size="picker.size.value" :total="picker.total.value" :busy="picker.busy.value" label="来源选章翻页" /></template><p v-if="!pickerSource" class="hint">选择来源后，在章节列表中点击添加。</p></div><form @submit.prevent="compose"><label>合并章节标题（可选）<input v-model="composedTitle" maxlength="300" placeholder="默认使用第一部分标题"></label><div class="parts"><p v-if="!parts.length" class="hint">从左侧添加章节，组成一份完整正文。</p><div v-for="(part,index) in parts" :key="index"><span class="part-number">{{ index+1 }}</span><span>{{ titleOf(part) }}<small>来源 #{{ part.source_id }} · 位置 {{ part.position }}</small></span><button type="button" class="icon-button" :aria-label="`移除第 ${index+1} 个部分`" @click="parts.splice(index,1)">×</button></div></div><div class="form-actions"><button class="button primary" :disabled="action.busy || !state.connected || !parts.length">组合 {{ parts.length }} 个部分并追加</button></div></form></div></section>
    <section ref="mergedDirectory" class="panel directory-panel"><div class="panel-heading"><div><h2>合并目录</h2></div></div><Pagination v-model:page="listing.page.value" v-model:size="listing.size.value" :total="listing.total.value" :busy="listing.busy.value" label="合并目录顶部翻页" @update:page="scrollToMerged" /><p v-if="listing.error.value" class="message error" role="alert">{{ listing.error.value }} <button class="text-button" @click="listing.load()">重试加载</button></p><div v-if="listing.busy.value && !listing.data.value" class="empty compact" role="status">正在加载合并目录…</div><div v-else-if="listing.data.value && !listing.data.value.items.length" class="empty compact">还没有合并章节。</div><div v-else-if="listing.data.value" class="table-wrap"><table><thead><tr><th>位置 / 标题</th><th>来源章节引用</th></tr></thead><tbody><tr v-for="chapter in listing.data.value.items" :key="chapter.id"><td><span class="position">{{ chapter.position }}</span><strong>{{ chapter.title || chapter.parts[0]?.normalized_title || '未命名章节' }}</strong></td><td><span v-for="(part,index) in chapter.parts" :key="index" class="reference">来源 #{{ part.source_id }} · {{ part.position }} 章</span></td></tr></tbody></table></div><Pagination v-model:page="listing.page.value" v-model:size="listing.size.value" :total="listing.total.value" :busy="listing.busy.value" label="合并目录翻页" @update:page="scrollToMerged" /></section>
  </template>
</template>
